  /** Iterate over listOperations() results across pages; offset
   * pagination is transparent, breaking out stops fetching. */
  async *iterOperations(options = {}) {
    const { pageSize = 1000, limit = null, ...filters } = options;
    if (!Number.isInteger(pageSize) || pageSize < 1 || pageSize > 1000) {
      throw new RangeError("pageSize must be an integer between 1 and 1000");
    }
    if (limit !== null && (!Number.isInteger(limit) || limit < 0)) {
      throw new RangeError("limit must be null or a non-negative integer");
    }
    let fetched = 0;
    let offset = 0;
    for (;;) {
      const size =
        limit === null ? pageSize : Math.min(pageSize, limit - fetched);
      if (size <= 0) {
        return;
      }
      const response = await this.listOperations({
        ...filters,
        limit: size,
        offset,
      });
      const page = response ?? [];
      if (!page.length) {
        return;
      }
      for (const item of page) {
        yield item;
        fetched += 1;
        if (limit !== null && fetched >= limit) {
          return;
        }
      }
      if (page.length < size) {
        return;
      }
      offset += page.length;
    }
  }

